#include "KS/SRC/ks/wave_perturb_shared.h"

typedef unsigned int u_int;

inline u_int SPLINE_BinarySearch(const float *x, u_int n, const float &valx)
{
    u_int lo = 0, hi = n - 1, mid;
    while (hi - lo > 1)
    {
        mid = (lo + hi) / 2;
        if (x[mid] < valx) lo = mid;
        else hi = mid;
    }
    return lo;
}

inline float SPLINE_Evaluate(const float *x, const float *a, const float *b, const float *c, const float *d,
    u_int n, float valx)
{
    u_int lo = SPLINE_BinarySearch(x, n, valx);
    valx -= x[lo];
    return ((a[lo] * valx + b[lo]) * valx + c[lo]) * valx + d[lo];
}

void SPLINE_ComputeCoeffs(const float *x, const float *y, int n, float *a, float *b, float *c, float *d);

#define WAVE_NUMPROFILEMAX 16
#define WAVE_NUMCONTROLMAX 16
struct rgba { float r, g, b, a; } __attribute__((aligned(16)));
struct WaveControlPoints {
    rgba color[WAVE_NUMPROFILEMAX][WAVE_NUMCONTROLMAX];
    float x[WAVE_NUMCONTROLMAX][WAVE_NUMPROFILEMAX];
    float y[WAVE_NUMCONTROLMAX][WAVE_NUMPROFILEMAX];
    float z[WAVE_NUMCONTROLMAX][WAVE_NUMPROFILEMAX];
    int region[WAVE_NUMCONTROLMAX][WAVE_NUMPROFILEMAX];
    int emitter[WAVE_NUMCONTROLMAX][WAVE_NUMPROFILEMAX];
    u_int numcontrol, numprofile;
} __attribute__((aligned(16)));

extern WaveControlPoints *WAVE_ControlPoints;
extern float WAVE_ProfileX[WAVE_NUMPROFILEMAX];
extern SplineCoeffs<WAVE_NUMPROFILEMAX> WAVE_ProfileToWorldCoeffs;

static float WAVE_ArtToProfile(float x)
{
    int floorx = (int) x;
    float fracx = x - floorx;
    return (1 - fracx) * WAVE_ProfileX[floorx] + fracx * WAVE_ProfileX[floorx+1];
}

template <int n> void WavePulsePerturbClass<n>::Init(void)
{
    float lo = SPLINE_Evaluate(WAVE_ProfileX,
            WAVE_ProfileToWorldCoeffs.a,
            WAVE_ProfileToWorldCoeffs.b,
            WAVE_ProfileToWorldCoeffs.c,
            WAVE_ProfileToWorldCoeffs.d,
            WAVE_ControlPoints->numprofile, WAVE_ArtToProfile(profilelo));
    float hi = SPLINE_Evaluate(WAVE_ProfileX,
            WAVE_ProfileToWorldCoeffs.a,
            WAVE_ProfileToWorldCoeffs.b,
            WAVE_ProfileToWorldCoeffs.c,
            WAVE_ProfileToWorldCoeffs.d,
            WAVE_ControlPoints->numprofile, WAVE_ArtToProfile(profilehi));
    float range = hi - lo;

    u_int jumpindex = 0;
    for (u_int i = 0; i < num; ++i)
    {
        pulsexx[i] = range * pulse[i];
        pulsex[i] = pulsexx[i];
        if (i > 0 && pulsexx[i] == pulsexx[i-1])
        {
            jumpindex = i;
        }
    }

    pulsex[jumpindex] += range;
    offset = hi - pulsex[jumpindex];

    SPLINE_ComputeCoeffs(pulsex, pulsexx, num, pulsecoeffs.a, pulsecoeffs.b, pulsecoeffs.c, pulsecoeffs.d);
}

template void WavePulsePerturbClass<6>::Init(void);
